using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L, C;
    cin >> L >> C;

    int P;
    cin >> P;

    vector<vector<bool>> black(L, vector<bool>(C, false));
    for (int i = 0; i < P; ++i) {
        int x, y;
        cin >> x >> y;
        black[x - 1][y - 1] = true;
    }

    const int dr[] = {-1, 1, 0, 0};
    const int dc[] = {0, 0, -1, 1};

    vector<vector<bool>> candidate(L, vector<bool>(C, false));
    int count = 0;

    for (int r = 0; r < L; ++r) {
        for (int c = 0; c < C; ++c) {
            if (black[r][c]) continue;

            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
                    candidate[r][c] = true;
                    ++count;
                    break;
                }
            }
        }
    }

    vector<vector<int>> adj(L * C);
    for (int r = 0; r < L; ++r) {
        for (int c = 0; c < C; ++c) {
            if (!candidate[r][c] || (r + c) % 2 != 0) continue;

            int u = r * C + c;
            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr >= 0 && nr < L && nc >= 0 && nc < C && candidate[nr][nc]) {
                    adj[u].push_back(nr * C + nc);
                }
            }
        }
    }

    vector<int> match(L * C, -1);
    int matching = 0;

    for (int r = 0; r < L; ++r) {
        for (int c = 0; c < C; ++c) {
            if ((r + c) % 2 != 0 || !candidate[r][c]) continue;

            vector<bool> seen(L * C, false);
            function<bool(int)> dfs = [&](int u) {
                for (int v : adj[u]) {
                    if (seen[v]) continue;
                    seen[v] = true;
                    if (match[v] == -1 || dfs(match[v])) {
                        match[v] = u;
                        return true;
                    }
                }
                return false;
            };

            if (dfs(r * C + c)) ++matching;
        }
    }

    cout << count - matching << '\n';
    return 0;
}
